+    type: 'unknown',
+    kind: 'future_widget',
+    frame: { v: 1, kind: 'future_widget', size: 3 },
+  });
+});
+
+test('unsupported versions are a LOUD version error', () => {
+  for (const v of [0, 2, 99]) {
+    assert.throws(
+      () => decodeEvent({ v, kind: 'agent_start' }),
+      WireVersionError,
+      `v=${v}`,
+    );
+    assert.throws(
+      () => decodeEvent({ kind: 'agent_start' }),
+      WireVersionError,
+      'missing v',
+    );
+  }
