+  isSecretField,
+  negotiate,
+  parseLine,
+  promptCommand,
+  redactForLog,
+  secretResponseCommand,
+  sessionControlCommand,
+  steerCommand,
+} from '../src/wire-client.ts';
+
+// Fixture dir resolved relative to THIS file: works from any working dir.
+const fixturesRoot = fileURLToPath(
