+  assert.equal(negotiate([1, 2]), 1);
+  assert.throws(() => negotiate([2, 3]), WireVersionError);
+  assert.equal(acceptWelcome({ v: 1, kind: 'welcome', version: 1 }), 1);
+  assert.throws(
