+    'ask_response': (f) =>
+      askResponseCommand(f.id, f.cancelled ? null : f.answers, f.v),
+    'secret_response': (f) =>
+      secretResponseCommand(
+        f.id,
+        f.granted
+          ? { name: f.name, value: f.value, persisted: f.persisted }
+          : null,
+        f.v,
+      ),
